<script setup lang="ts">
import TaskDependencyBadge from './TaskDependencyBadge.vue'
import {orderTaskTree as ordered} from './task-order'
import { computed,ref,onMounted,onUnmounted,nextTick,watch,useId } from 'vue'
import type { LiveProject,ProjectTask,ProjectMilestone } from './project-api'
const props=defineProps<{project:LiveProject}>()
const day=86400000,collapsed=ref<string[]>([])
const scroll=ref<HTMLElement>(),viewportWidth=ref(1040),nameWidth=ref(400),zoom=ref(1)
const zoomLevels=[0.125,0.25,0.5,0.75,1,1.5,2,3,4,6,8,12]
const baseAxisWidth=computed(()=>Math.max(640,viewportWidth.value-nameWidth.value))
const axisWidth=computed(()=>baseAxisWidth.value*Math.max(1,zoom.value))
const tableWidth=computed(()=>nameWidth.value+axisWidth.value)
const canvas=ref<HTMLElement>(),dependencyLines=ref<{key:string;path:string;label:string}[]>([]),canvasHeight=ref(0)
const arrowId=useId()
function measureDependencies(){
 const el=canvas.value;if(!el)return;const origin=el.getBoundingClientRect();canvasHeight.value=el.offsetHeight
 const rows=[...el.querySelectorAll<HTMLElement>('.pg-task')]
 const lines:{key:string;path:string;label:string}[]=[]
 for(const row of rows){const task=props.project.tasks.find(t=>t.id===row.dataset.taskId);if(!task?.dependsOn)continue
 const sources=rows.filter(r=>r.dataset.taskId===task.dependsOn),source=sources.find(r=>r.closest('tbody')===row.closest('tbody'))||sources[0]
 const from=source?.querySelector<HTMLElement>('.gantt-bar'),to=row.querySelector<HTMLElement>('.gantt-bar');if(!from||!to)continue
 const a=from.getBoundingClientRect(),b=to.getBoundingClientRect();if(!a.width||!b.width)continue
 const x1=a.right-origin.left,y1=a.top-origin.top+a.height/2,x2=b.left-origin.left,y2=b.top-origin.top+b.height/2
 const bend=x2>x1+20?(x1+x2)/2:Math.min(origin.width-4,x1+12),lane=(y1+y2)/2
 const path=x2>x1+20?`M ${x1} ${y1} H ${bend} V ${y2} H ${x2}`:`M ${x1} ${y1} H ${bend} V ${lane} H ${Math.max(nameWidth.value+4,x2-10)} V ${y2} H ${x2}`
 lines.push({key:row.closest('tbody')?.dataset.milestoneId+'-'+task.id,path,label:`${props.project.tasks.find(t=>t.id===task.dependsOn)?.title} → ${task.title}`})
 }dependencyLines.value=lines
}
watch(()=>[zoom.value,collapsed.value.join(','),props.project],async()=>{await nextTick();measureDependencies()},{deep:true})
let observer:ResizeObserver|undefined
onMounted(()=>{const el=scroll.value;if(!el)return;observer=new ResizeObserver(()=>{viewportWidth.value=el.clientWidth;nameWidth.value=parseFloat(getComputedStyle(el).getPropertyValue('--gantt-name-width'))||400;nextTick().then(measureDependencies)});observer.observe(el);if(canvas.value)observer.observe(canvas.value)})
onUnmounted(()=>observer?.disconnect())
async function setZoom(value:number){const el=scroll.value,available=(el?.clientWidth||viewportWidth.value)-nameWidth.value;const centerDays=((el?.scrollLeft||0)+available/2)/axisWidth.value*duration.value;zoom.value=value;await nextTick();if(el)el.scrollLeft=Math.max(0,centerDays/duration.value*axisWidth.value-available/2)}
function stepZoom(direction:number){const index=zoomLevels.indexOf(zoom.value);return setZoom(zoomLevels[Math.max(0,Math.min(zoomLevels.length-1,index+direction))]!)}
async function resetZoom(){zoom.value=1;await nextTick();if(scroll.value)scroll.value.scrollLeft=0}

const valid=(date:string)=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Date.parse(date))
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const dataRange=computed(()=>{const dates=[props.project.start,props.project.end,...props.project.tasks.flatMap(t=>[t.start,t.due]),...(props.project.milestones||[]).flatMap(m=>[m.planned,m.actual])].filter(valid).sort();return {start:dates[0]||today,end:dates.at(-1)||today}})
const range=computed(()=>{const source=dataRange.value;if(zoom.value>=1)return source;const days=(Date.parse(source.end)-Date.parse(source.start))/day+1;return {start:source.start,end:new Date(Date.parse(source.start)+(Math.ceil(days/zoom.value)-1)*day).toISOString().slice(0,10)}})
const duration=computed(()=>Date.parse(range.value.end)-Date.parse(range.value.start)+day)
const position=(date:string)=>`${(Date.parse(date)-Date.parse(range.value.start)+day/2)/duration.value*100}%`
const bar=(task:ProjectTask)=>({left:`${(Date.parse(task.start)-Date.parse(range.value.start))/duration.value*100}%`,width:`${(Date.parse(task.due)-Date.parse(task.start)+day)/duration.value*100}%`})
const ticks=computed(()=>{const count=Math.min(Math.max(1,Math.round(duration.value/day)),Math.max(2,Math.floor(axisWidth.value/120)));return Array.from({length:count},(_,i)=>{const offset=Math.round(i*(duration.value/day-1)/Math.max(1,count-1));return {date:new Date(Date.parse(range.value.start)+offset*day).toISOString().slice(0,10),left:`${(offset+0.5)*day/duration.value*100}%`}})})
const groups=computed(()=>{
 const used=new Set<string>();const groups:{id:string;milestone?:ProjectMilestone;tasks:ProjectTask[]}[]=(props.project.milestones||[]).slice().sort((a,b)=>a.planned.localeCompare(b.planned)).map(m=>{
  const ids=new Set(m.taskIds);let changed=true;while(changed){changed=false;for(const t of props.project.tasks)if(t.parentId&&ids.has(t.parentId)&&!ids.has(t.id)){ids.add(t.id);changed=true}}
  const tasks=ordered(props.project.tasks.filter(t=>ids.has(t.id)));tasks.forEach(t=>used.add(t.id));return {id:m.id,milestone:m,tasks}
 });const ungrouped=ordered(props.project.tasks.filter(t=>!used.has(t.id)));if(ungrouped.length)groups.push({id:'unassigned',tasks:ungrouped});return groups
})
function depth(task:ProjectTask,tasks:ProjectTask[]){let parent=task.parentId,n=0;const visited=new Set<string>();while(parent&&!visited.has(parent)){visited.add(parent);const t=tasks.find(t=>t.id===parent);if(!t)break;n++;parent=t.parentId}return Math.min(n,5)}
function toggle(id:string){collapsed.value=collapsed.value.includes(id)?collapsed.value.filter(v=>v!==id):[...collapsed.value,id]}
const inRange=computed(()=>today>=range.value.start&&today<=range.value.end)
</script>
<template>
 <section class="panel detail-section project-gantt"><div class="pg-heading"><div><h2>项目甘特图</h2></div><div class="pg-controls"><button aria-label="缩小时间轴" :disabled="zoom===zoomLevels[0]" @click="stepZoom(-1)">−</button><select aria-label="时间轴缩放" :value="zoom" @change="setZoom(Number(($event.target as HTMLSelectElement).value))"><option v-for="level in zoomLevels" :key="level" :value="level">{{ level*100 }}%</option></select><button aria-label="放大时间轴" :disabled="zoom===zoomLevels.at(-1)" @click="stepZoom(1)">＋</button><button @click="resetZoom">重置缩放</button><button @click="collapsed=[]">展开全部</button><button @click="collapsed=groups.map(g=>g.id)">收起全部</button></div></div>
 <div class="pg-legend"><span><i class="pg-diamond"></i>里程碑计划日期</span><span><i class="pg-diamond actual"></i>实际完成日期</span><span><i class="pg-key-bar"></i>未完成任务</span><span><i class="pg-key-bar done"></i>已完成任务</span><span><i class="pg-key-today"></i>今天</span><span class="pg-dependency-legend">→ 前置任务 → 后续任务</span></div>
 <div ref="scroll" class="gantt-scroll pg-scroll"><div ref="canvas" class="pg-canvas" :style="{width:tableWidth+'px'}"><table class="pg-table" :style="{width:tableWidth+'px'}" aria-label="项目里程碑与任务甘特图"><thead><tr><th>里程碑 / 任务</th><th><div class="pg-axis"><time v-for="tick in ticks" :key="tick.date" :style="{left:tick.left}">{{ tick.date }}</time></div></th></tr></thead>
 <tbody v-for="group in groups" :key="group.id" :aria-label="group.milestone?.title||'未关联里程碑的任务'" :data-milestone-id="group.id"><tr class="pg-group"><th scope="row"><button class="pg-collapse" :title="`${group.milestone?.title||'未关联里程碑的任务'}（${group.tasks.length}项任务）`" :aria-expanded="!collapsed.includes(group.id)" @click="toggle(group.id)">{{ collapsed.includes(group.id)?'▸':'▾' }} {{ group.milestone?.title||'未关联里程碑的任务' }} <span>（{{ group.tasks.length }}项任务）</span></button></th><td><div class="pg-track"><i v-for="tick in ticks" :key="tick.date" class="pg-date-line" :style="{left:tick.left}"></i><i v-if="inRange" class="pg-today" :style="{left:position(today)}"></i><template v-if="group.milestone"><span class="pg-marker" :style="{left:position(group.milestone.planned)}" :title="`${group.milestone.title} · 计划 ${group.milestone.planned} · ${group.milestone.state}`" :aria-label="`${group.milestone.title}计划日期 ${group.milestone.planned}`"><i class="pg-diamond"></i></span><span v-if="group.milestone.actual" class="pg-marker pg-actual-marker" :style="{left:position(group.milestone.actual)}" :title="`${group.milestone.title} · 实际完成 ${group.milestone.actual}`" :aria-label="`${group.milestone.title}实际完成日期 ${group.milestone.actual}`"><i class="pg-diamond actual"></i></span></template></div></td></tr>
 <template v-if="!collapsed.includes(group.id)"><tr v-for="task in group.tasks" :key="task.id" class="pg-task" :data-task-id="task.id"><th scope="row"><div :style="{paddingLeft:(16+depth(task,group.tasks)*14)+'px'}"><strong :title="task.title">{{ task.parentId?'↳ ':'' }}{{ task.title }}</strong><TaskDependencyBadge :task="task" :tasks="project.tasks" /></div></th><td><div class="pg-track"><i v-for="tick in ticks" :key="tick.date" class="pg-date-line" :style="{left:tick.left}"></i><i v-if="inRange" class="pg-today" :style="{left:position(today)}"></i><span class="gantt-bar" :class="{done:task.state==='已完成'}" :style="bar(task)" :title="`${task.title} · ${task.start} 至 ${task.due} · ${task.progress}%`" :aria-label="`${task.title}任务周期 ${task.start} 至 ${task.due}，进度 ${task.progress}%`"><i :style="{width:task.progress+'%'}"></i></span></div></td></tr><tr v-if="group.milestone&&!group.tasks.length" class="pg-empty-group"><td colspan="2">该里程碑尚未关联任务，可在里程碑编辑中选择任务。</td></tr></template></tbody></table><svg class="pg-dependencies" :width="tableWidth" :height="canvasHeight" aria-label="任务依赖箭头"><defs><marker :id="arrowId" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0,0 L7,3.5 L0,7 Z" fill="#315d94" /></marker><clipPath :id="arrowId+'-clip'"><rect :x="nameWidth+1" y="0" :width="axisWidth" :height="canvasHeight" /></clipPath></defs><g :clip-path="`url(#${arrowId}-clip)`"><path v-for="line in dependencyLines" :key="line.key" :d="line.path" fill="none" stroke="#315d94" stroke-width="1.5" :marker-end="`url(#${arrowId})`" :aria-label="line.label"><title>{{ line.label }}</title></path></g></svg></div></div>
 <p v-if="!groups.length" class="muted">暂无里程碑或任务排期。</p>
 </section>
</template>
<style scoped>
.pg-canvas{position:relative}.pg-dependencies{position:absolute;top:0;left:0;pointer-events:none;z-index:2}.pg-dependency-legend{color:var(--project-blue,#315d94)}.pg-task th:first-child>div{display:flex;align-items:center;gap:6px}.pg-task strong{min-width:0}

.project-gantt{min-width:0;padding:12px}.pg-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;margin-bottom:8px}.pg-heading h2{margin:0}.pg-controls{display:flex;gap:6px;flex-wrap:wrap}.pg-controls button,.pg-controls select{font:inherit;padding:6px 9px;background:white;border:1px solid var(--line);border-radius:5px}.pg-legend{display:flex;flex-wrap:wrap;gap:15px;color:var(--muted);font-size:13px;margin:8px 0}.pg-legend>span{display:flex;align-items:center;gap:7px}.pg-diamond{display:inline-block;width:10px;height:10px;transform:rotate(45deg);background:var(--accent,#a5512b);border:1px solid white}.pg-diamond.actual{background:#39856d}.pg-key-bar{width:24px;height:7px;border-radius:3px;background:#c28159}.pg-key-bar.done{background:#39856d}.pg-key-today{height:12px;border-left:2px dashed #bb493a}.pg-scroll{--gantt-name-width:400px;overflow:auto;border:1px solid var(--line);border-radius:6px}.pg-table{table-layout:fixed;border-collapse:separate;border-spacing:0;text-align:left;font-size:14px}.pg-table th:first-child{width:var(--gantt-name-width)}.pg-table th,.pg-table td{border-bottom:1px solid var(--line);padding:0;vertical-align:middle}.pg-table th:first-child{position:sticky;left:0;z-index:3;background:white;border-right:1px solid var(--line)}.pg-table thead th{background:#f6f5f3;font-weight:600;height:36px}.pg-table thead th:first-child{padding:10px}.pg-axis{position:relative;height:36px;margin:0 12px}.pg-axis time{position:absolute;top:9px;transform:translateX(-50%);font-size:12px;white-space:nowrap}.pg-axis time:first-child{transform:none}.pg-axis time:last-child{transform:translateX(-100%)}.pg-group th:first-child{background:#f4f0eb;padding:6px 8px}.pg-group td{background:#f4f0eb}.pg-collapse{background:none;border:0;text-align:left;font:inherit;font-weight:600;cursor:pointer;color:inherit;padding:0}.pg-collapse{display:block;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pg-collapse span{font-weight:400;white-space:nowrap}.pg-task th:first-child{padding:6px 8px}.pg-task strong{display:block;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.pg-track{position:relative;height:34px;margin:0 12px;background:none}.pg-date-line{position:absolute;top:0;bottom:0;border-left:1px solid #e8e3dd;pointer-events:none}.pg-marker{position:absolute;top:8px;transform:translateX(-50%);z-index:2;line-height:10px}.pg-actual-marker{top:22px}.pg-today{position:absolute;top:0;bottom:0;border-left:1px dashed #bb493a;z-index:1;pointer-events:none}.pg-track .gantt-bar{position:absolute;display:block;top:12px;height:11px;min-width:2px;background:#ead4c3;border:1px solid #cda17f;border-radius:4px;overflow:hidden}.pg-track .gantt-bar>i{display:block;height:100%;background:#b66b3d}.pg-track .gantt-bar.done{background:#cee7dd;border-color:#6aa98e}.pg-track .gantt-bar.done>i{background:#39856d}.pg-empty-group td{padding:10px 26px;color:var(--muted);background:#faf9f7}@media(max-width:720px){.pg-heading{flex-wrap:wrap}.pg-scroll{--gantt-name-width:280px}.pg-legend{gap:10px}.pg-group th:first-child{padding:6px 8px}}
.pg-controls button:disabled{opacity:.45;cursor:default}.pg-controls select{min-width:80px}</style>
